const crypto = require('crypto');
const hmac = (message) => crypto.createHmac('sha256', $env.N8N_SHARED_SECRET).update(message).digest('hex');
const safeEqual = (signature, expected) => {
  if (!/^[a-f0-9]{64}$/i.test(String(signature))) return false;
  return crypto.timingSafeEqual(Buffer.from(String(signature), 'hex'), Buffer.from(expected, 'hex'));
};

const input = $input.first();
const headers = input.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
const eventId = String(headers['x-lendloop-event-id'] || '');
if (!timestamp || !signature || !eventId) throw new Error('Missing LendLoop signature headers');
if (!Number.isFinite(Number(timestamp)) || Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) {
  throw new Error('Stale or invalid webhook timestamp');
}

// Verify the exact bytes Convex signed (the webhook's "Raw body" option), never a re-serialised copy.
if (!input.binary?.data) throw new Error('Raw request body is unavailable');
const rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
if (!safeEqual(signature, hmac(`${timestamp}.POST./webhook/lendloop-request-events.${rawBody}`))) {
  throw new Error('Invalid webhook signature');
}
const event = JSON.parse(rawBody);
if (event.eventId !== eventId) throw new Error('Event ID header does not match the signed body');

// Replay protection: event IDs are remembered for longer than the timestamp window.
// Production executions persist workflow static data; an ID is stored only after its
// notification was sent, so a Convex retry after a failed send is still processed.
const store = $getWorkflowStaticData('global');
store.deliveredEventIds = store.deliveredEventIds || {};
const cutoff = Date.now() - 15 * 60 * 1000;
for (const [id, seenAt] of Object.entries(store.deliveredEventIds)) {
  if (seenAt < cutoff) delete store.deliveredEventIds[id];
}
const duplicate = Boolean(store.deliveredEventIds[eventId]);
return [{ json: { event, eventId, timestamp, duplicate } }];

// Only the minimal fields Convex sent are used: recipient, display names, tool, dates, status.
const e = $json.event;
const subjects = {
  'request.created': `New request for ${e.toolName}`,
  'request.approved': `Your ${e.toolName} request was approved`,
  'request.declined': `Update on your ${e.toolName} request`,
  'request.cancelled': `Cancelled request for ${e.toolName}`,
};
const statusLine = e.message || (e.status === 'pending' ? `${e.borrowerName} would like to borrow it` : `Your request is now ${e.status}`);
return [{ json: { eventId: $json.eventId, mail: {
  From: { Email: 'notifications@lendloop.local', Name: 'LendLoop' },
  To: [{ Email: e.recipientEmail, Name: e.recipientName }],
  Subject: subjects[e.type] || 'LendLoop request update',
  Text: `Hi ${e.recipientName}, ${statusLine}. Dates: ${e.startDate} to ${e.endDate}.`,
} } }];

// The notification was sent: remember the event ID so a replay or retry is acknowledged without a second email.
const { eventId } = $('Verify signature and replay').first().json;
const store = $getWorkflowStaticData('global');
store.deliveredEventIds = store.deliveredEventIds || {};
store.deliveredEventIds[eventId] = Date.now();
return [{ json: { eventId, delivered: true } }];

const crypto = require('crypto');
const verified = $('Verify signature and replay').first().json;
const body = JSON.stringify({ ok: true, duplicate: verified.duplicate });
const signature = crypto.createHmac('sha256', $env.N8N_SHARED_SECRET)
  .update(`${verified.timestamp}.200./webhook/lendloop-request-events.${body}`)
  .digest('hex');
return [{ json: { body, timestamp: verified.timestamp, signature } }];
